const updateSubscription = `-- name: UpdateSubscription :one
UPDATE tenant_subscriptions
SET plan_id = $1, status = $2, paid_through = $3, grace_days = $4,
    max_properties_override = $5, max_rooms_override = $6,
    max_users_override = $7, version = version + 1
WHERE tenant_id = $8
RETURNING id, tenant_id, plan_id, status, started_on, paid_through, grace_days, max_properties_override, max_rooms_override, max_users_override, version, created_at, updated_at
`

type UpdateSubscriptionParams struct {
	PlanID                int64
	Status                string
	PaidThrough           *civil.Date
	GraceDays             int16
	MaxPropertiesOverride pgtype.Int4
	MaxRoomsOverride      pgtype.Int4
	MaxUsersOverride      pgtype.Int4
	TenantID              int64
}

func (q *Queries) UpdateSubscription(ctx context.Context, arg UpdateSubscriptionParams) (TenantSubscription, error) {
	row := q.db.QueryRow(ctx, updateSubscription,
		arg.PlanID,
		arg.Status,
		arg.PaidThrough,
		arg.GraceDays,
		arg.MaxPropertiesOverride,
		arg.MaxRoomsOverride,
		arg.MaxUsersOverride,
		arg.TenantID,
	)
	var i TenantSubscription
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.PlanID,
		&i.Status,
		&i.StartedOn,
		&i.PaidThrough,
		&i.GraceDays,
		&i.MaxPropertiesOverride,
		&i.MaxRoomsOverride,
		&i.MaxUsersOverride,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const usage = `-- name: Usage :one
SELECT
    (SELECT count(*) FROM properties p WHERE p.tenant_id = $1 AND p.status = 'ACTIVE')::int AS properties,
    (SELECT count(*) FROM rooms r WHERE r.tenant_id = $1 AND r.is_active)::int              AS rooms,
    (SELECT count(*) FROM users u WHERE u.tenant_id = $1 AND u.is_active)::int              AS users
`

type UsageRow struct {
	Properties int32
	Rooms      int32
	Users      int32
}

func (q *Queries) Usage(ctx context.Context, tenantID int64) (UsageRow, error) {
	row := q.db.QueryRow(ctx, usage, tenantID)
	var i UsageRow
	err := row.Scan(&i.Properties, &i.Rooms, &i.Users)
	return i, err
}
